styl:
.w290 { max-width: 290px;
  width: 70%; }
.bg-img-bottom { background: url("https://fsms.quadcode.com/storage/public/d6/28/aj0ggnfnh4cs78rg/332-foot.png") center no-repeat;
  background-size: cover;
  background-color: #fff; }
@media screen and (max-width: 600px) {
  .bg-img-bottom { background: url("https://fsms.quadcode.com/storage/public/d6/28/aj0ggnfnh4cs78rg/332-foot.png") center no-repeat !important;
    background-size: cover !important; }
}
.brad-full { border-radius: 32px !important; }
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 24px !important;
    line-height: 32px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb32 { padding-bottom: 32px; }
.pb44 { padding-bottom: 44px; }
.pt44 { padding-top: 44px; }
.h-40 { font-size: 8px;
  line-height: 40px;
  height: 40px; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
